/* Compiled AFTER model_weights.h is generated by training.
 * Compile with -Ic -Iresults. The platform handles sensor sampling and SQI. */
#include "ppg.h"
#include "model_weights.h"
static ppg_workspace workspace; /* Allocate once; do not put ~68KiB on task stack. */
int estimate_bpm(const float raw_window[1000],float *bpm) {
    return ppg_infer(&ppg_trained_model,&workspace,raw_window,bpm);
}
